package com.mygo.music;
import android.app.*;
import android.content.*;
import android.media.*;
import android.net.Uri;
import android.os.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** Read-only public live-radio transport diagnosis; credentials and full URLs are not exported. */
final class RoamDialDiagnostic {
 final Instrumentation test;final JSONArray rows=new JSONArray();final BilibiliTransportDiagnostic shared;
 RoamDialDiagnostic(Instrumentation test){this.test=test;shared=new BilibiliTransportDiagnostic(test);}
 File dir(){File p=new File(test.getTargetContext().getExternalFilesDir(null),"qa/roamdial");p.mkdirs();return p;}
 void save()throws Exception{try(FileOutputStream out=new FileOutputStream(new File(dir(),"comparison.json"))){out.write(new JSONObject().put("scope","anonymous read-only public station tests; no account login or remote writes; no credentials or complete source URLs exported").put("rows",rows).toString(2).getBytes("UTF-8"));}}
 JSONObject nativeAudio(String address,Map<String,String> headers,String mode)throws Exception{
  JSONObject result=new JSONObject().put("mode",mode);MediaPlayer[] player={null};CountDownLatch done=new CountDownLatch(1);long started=SystemClock.elapsedRealtime();
  try{test.runOnMainSync(()->{try{HashMap<String,String> values=new HashMap<>(headers);if(!mode.equals("plain"))values=PluginMedia.progressiveHeaders(values);if(mode.equals("icy-off"))values.put("Icy-MetaData","0");values.put("android-allow-cross-domain-redirect","0");MediaPlayer p=new MediaPlayer();player[0]=p;p.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());p.setDataSource(test.getTargetContext(),Uri.parse(address),values);p.setOnPreparedListener(mp->{try{result.put("prepared",true).put("prepareMs",SystemClock.elapsedRealtime()-started).put("durationMs",mp.getDuration());mp.setVolume(0,0);mp.start();new Handler(Looper.getMainLooper()).postDelayed(()->{try{int count=0;for(MediaPlayer.TrackInfo info:mp.getTrackInfo())if(info.getTrackType()==MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_AUDIO)count++;result.put("positionMs",mp.getCurrentPosition()).put("playing",mp.isPlaying()).put("audioTracks",count).put("clockAdvanced",mp.getCurrentPosition()>150);}catch(Exception e){}done.countDown();},2000);}catch(Exception e){done.countDown();}});p.setOnErrorListener((mp,what,extra)->{try{result.put("what",what).put("extra",extra);}catch(Exception e){}done.countDown();return true;});p.prepareAsync();}catch(Exception e){try{result.put("error",e.getMessage());}catch(Exception ignored){}done.countDown();}});result.put("completed",done.await(25,TimeUnit.SECONDS));}finally{test.runOnMainSync(()->{if(player[0]!=null)player[0].release();});}
  return result.put("millis",SystemClock.elapsedRealtime()-started);
 }
 JSONObject http(String address,Map<String,String> original,String mode,File sample)throws Exception{
  JSONObject result=new JSONObject().put("mode",mode);HashMap<String,String> headers=new HashMap<>(original);if(!mode.equals("plain"))headers=PluginMedia.progressiveHeaders(headers);if(mode.equals("icy-off"))headers.put("Icy-MetaData","0");long begin=SystemClock.elapsedRealtime();
  try(PluginMedia.Connection c=PluginMedia.open(address,headers,false)){c.http.setReadTimeout(8000);result.put("status",c.http.getResponseCode()).put("resolvedHost",c.http.getURL().getHost()).put("type",c.http.getContentType()).put("length",c.http.getContentLengthLong()).put("range",c.http.getHeaderField("Content-Range")).put("icyMetaInt",c.http.getHeaderField("icy-metaint")).put("icyBitRate",c.http.getHeaderField("icy-br"));try(InputStream in=c.http.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while(out.size()<65536&&SystemClock.elapsedRealtime()-begin<10000&&(n=in.read(b,0,Math.min(b.length,65536-out.size())))!=-1)out.write(b,0,n);byte[] data=out.toByteArray();result.put("bytesRead",data.length);StringBuilder hex=new StringBuilder();for(int i=0;i<Math.min(96,data.length);i++)hex.append(String.format(Locale.ROOT,"%02x",data[i]&255));result.put("prefixHex",hex.toString());if(data.length>0)try(FileOutputStream file=new FileOutputStream(sample)){file.write(data);}}}catch(Exception e){result.put("error",e.getMessage());}
  return result.put("millis",SystemClock.elapsedRealtime()-begin);
 }
 void run()throws Exception{
  MainActivity activity=null;PluginManager manager=null;
  try{JSONArray pins=new JSONArray(shared.read(test.getContext().getAssets().open("market-audit/index.json")));JSONObject pin=null;for(int i=0;i<pins.length();i++)if(pins.getJSONObject(i).getString("repo").equals("GYRYEZ/mygo-music-roamdial"))pin=pins.getJSONObject(i);if(pin==null)throw new IOException("pinned RoamDial missing");activity=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));manager=new PluginManager(activity);CountDownLatch installed=new CountDownLatch(1);boolean[] ok={false};manager.installZipStream(test.getContext().getAssets().open("market-audit/"+pin.getString("archive")),pin.getString("repo"),(yes,raw)->{ok[0]=yes;installed.countDown();});if(!installed.await(40,TimeUnit.SECONDS)||!ok[0])throw new IOException("source install failed");String id=pin.getString("declaredId");test.getTargetContext().getSharedPreferences("library",0).edit().putBoolean("plugin_network_"+id,false).commit();CountDownLatch consent=new CountDownLatch(1);manager.authorizeNetwork(id,(yes,raw)->{ok[0]=yes;consent.countDown();});SourcePlaylistUiChecks.click(test,"允许并继续");if(!consent.await(10,TimeUnit.SECONDS)||!ok[0])throw new IOException("network consent failed");
   LinkedHashSet<String> ids=new LinkedHashSet<>();ids.add("6dea6c7d9b22");BilibiliTransportDiagnostic.Answer search=shared.call(manager,id,"search",new JSONObject().put("query","love").put("kind","tracks").put("offset",0));if(search.ok){JSONArray found=new JSONObject(search.value).optJSONArray("tracks");if(found!=null)for(int i=0;i<Math.min(3,found.length())&&ids.size()<1;i++)ids.add(found.getJSONObject(i).getString("id"));}
   int index=0;for(String track:ids){JSONObject row=new JSONObject().put("stationId",track);rows.put(row);save();BilibiliTransportDiagnostic.Answer answer=shared.call(manager,id,"stream",new JSONObject().put("id",track).put("quality","high"));if(!answer.ok){row.put("sourceError",answer.value);save();continue;}JSONObject source=new JSONObject(answer.value);String address=source.getString("url");HashMap<String,String> headers=manager.mediaHeaders(id,address,"audio",source.optJSONObject("headers"));try(PluginMedia.Connection c=PluginMedia.open(address,headers,true)){address=c.http.getURL().toString();headers=new HashMap<>(c.headers);row.put("host",c.http.getURL().getHost()).put("type",source.optString("type")).put("probeStatus",c.http.getResponseCode());}if(!PluginMedia.contains(headers,"User-Agent"))headers.put("User-Agent","MyGoMusic/5.11");for(String mode:new String[]{"ranged"}){File sample=new File(dir(),"sample-"+index+"-"+mode+".bin");row.put("http-"+mode,http(address,headers,mode,sample));row.put("native-"+mode,nativeAudio(address,headers,mode));if(sample.exists()&&sample.length()>4096)row.put("file-"+mode,nativeAudio(sample.toURI().toString(),new HashMap<>(),"plain"));save();}try(LiveAacPlayback live=new LiveAacPlayback(address,headers)){row.put("native-live-adapter",nativeAudio(live.address(),new HashMap<>(),"plain"));row.put("adapter-state",new JSONObject().put("failure",live.failure()).put("publishedSegments",live.publishedSegments()).put("retainedBytes",live.retainedBytes()).put("sampleRate",live.sampleRate()).put("channels",live.channels()));save();}index++;}
  }finally{PluginManager m=manager;MainActivity a=activity;test.runOnMainSync(()->{if(m!=null)m.close();if(a!=null)a.finish();});}
 }
}
